// @vitest-environment node
import { readFile } from 'node:fs/promises';
import openapiTS, { astToString, type OpenAPI3 } from 'openapi-typescript';
import { describe, expect, it } from 'vitest';

const spec = new URL('../../../api/openapi.json', import.meta.url);
const committed = new URL('./schema.d.ts', import.meta.url);

/** What the openapi-typescript CLI (used by `api:generate`) puts above the generated types. */
const HEADER = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;

describe('generated API types', () => {
  it('match apps/api/openapi.json (run `pnpm --filter @tracker/web api:generate` to update)', async () => {
    const document = JSON.parse(await readFile(spec, 'utf8')) as OpenAPI3;
    const generated = HEADER + astToString(await openapiTS(document));
    expect(await readFile(committed, 'utf8')).toBe(generated);
  });
});
